"""Unit tests of CheckDiscrete, the two-exit corridor."""

import numpy as np
import pytest

from rllab.core import ActionError
from rllab.worlds.checks import CheckDiscrete

LEFT, RIGHT = 0, 1


def cell_of(obs: np.ndarray) -> int | None:
    row = obs.reshape(-1)
    return int(np.argmax(row)) if row.any() else None


@pytest.mark.unit
def test_checkdiscrete_reset_starts_on_one_cell_with_no_reward() -> None:
    step = CheckDiscrete().reset(0)
    assert step.obs.shape == (1, 6)
    assert step.obs.sum() == 1.0
    assert step.rewards.tolist() == [0.0]
    assert step.active.tolist() == [True]
    assert not step.done
    assert not step.truncated


@pytest.mark.unit
def test_checkdiscrete_starts_spread_over_the_cells() -> None:
    starts = {cell_of(CheckDiscrete().reset(seed).obs) for seed in range(60)}
    assert starts == {0, 1, 2, 3, 4, 5}


@pytest.mark.unit
def test_checkdiscrete_moves_one_cell_per_action() -> None:
    world = CheckDiscrete()
    start = cell_of(world.reset(0).obs)
    assert start == 3
    assert cell_of(world.step(np.asarray([RIGHT])).obs) == 4
    assert cell_of(world.step(np.asarray([LEFT])).obs) == 3
    assert cell_of(world.step(np.asarray([LEFT])).obs) == 2


@pytest.mark.unit
def test_checkdiscrete_left_exit_ends_with_zero_obs_and_its_result() -> None:
    world = CheckDiscrete()
    world.reset(0)
    steps = [world.step(np.asarray([LEFT])) for _ in range(4)]
    assert [s.done for s in steps] == [False, False, False, True]
    assert [float(s.rewards[0]) for s in steps] == pytest.approx([0.0, 0.0, 0.0, 0.8])
    assert not steps[-1].obs.any()
    assert not steps[-1].truncated
    result = world.result()
    assert result.seed == 0
    assert result.length == 4
    assert result.scores == pytest.approx({"agent": 0.8})
    assert result.team_rewards == pytest.approx({"agent": 0.8})
    assert result.measures == {}


@pytest.mark.unit
def test_checkdiscrete_step_after_done_raises() -> None:
    world = CheckDiscrete()
    world.reset(0)
    for _ in range(3):
        world.step(np.asarray([RIGHT]))
    with pytest.raises(RuntimeError):
        world.step(np.asarray([RIGHT]))


@pytest.mark.unit
def test_checkdiscrete_step_before_reset_raises() -> None:
    with pytest.raises(RuntimeError):
        CheckDiscrete().step(np.asarray([RIGHT]))


@pytest.mark.unit
def test_checkdiscrete_truncates_at_max_steps() -> None:
    world = CheckDiscrete(max_steps=2)
    world.reset(0)
    first = world.step(np.asarray([LEFT]))
    second = world.step(np.asarray([RIGHT]))
    assert not first.done
    assert second.done
    assert second.truncated
    assert cell_of(second.obs) == 3
    assert world.result().scores == {"agent": 0.0}


@pytest.mark.unit
def test_checkdiscrete_names_an_unknown_override() -> None:
    with pytest.raises(ValueError, match="lives"):
        CheckDiscrete(lives=3)


@pytest.mark.unit
@pytest.mark.parametrize("bad", [np.asarray([1.0]), np.asarray([1, 0]), np.asarray(1)])
def test_checkdiscrete_rejects_a_non_integer_or_misshaped_action(bad: np.ndarray) -> None:
    world = CheckDiscrete()
    world.reset(0)
    with pytest.raises(ActionError):
        world.step(bad)


@pytest.mark.unit
def test_checkdiscrete_draw_shows_both_exits_and_the_agent_until_it_leaves() -> None:
    world = CheckDiscrete()
    world.reset(0)
    draw = world.draw()
    assert (draw.width, draw.height) == (8.0, 1.0)
    assert [(o.kind, o.x) for o in draw.objects] == [("exit", -1.0), ("exit", 6.0), ("agent", 3.0)]
    for _ in range(3):
        world.step(np.asarray([RIGHT]))
    assert [o.kind for o in world.draw().objects] == ["exit", "exit"]


@pytest.mark.unit
def test_checkdiscrete_states_are_one_hot_in_cell_order() -> None:
    assert np.array_equal(CheckDiscrete().states(), np.eye(6))

